    private static final long DAY_MS=15*60*1000L,NIGHT_MS=10*60*1000L,CYCLE_MS=DAY_MS+NIGHT_MS,WEATHER_MS=4*60*1000L;
    private final ContentRepository repo;private final Listener listener;private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG),pixel=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);
    private float playerX,playerY,insideX,insideY,insideLimitX=4.5f,insideLimitY=2.7f;private int health,energy;private final long seed,worldStart;private float joyX,joyY;private int joyPointer=-1,directionRow;private boolean walking,inside,insideCave;private long insideHouseId=-1,lastFrame=System.nanoTime(),lastSave,lastEntityLoad;private String toast="Explore, gather, build, and survive";private long toastUntil=System.currentTimeMillis()+5000;
