    private final Bitmap playerSheet,itemAtlas,buildAtlas,mobSheet,structureAtlas;private final WorldTextureCache worldTextures;private final Map<Long,Long> harvested=new HashMap<>();private final Map<String,ContentItem> creatureInfo=new HashMap<>(),structureInfo=new HashMap<>();private final Map<String,Bitmap> generatedMobSprites=new HashMap<>(),generatedStructureSprites=new HashMap<>();
